import { getDeliveryBadge } from "./solution";

function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

const cases: ReadonlyArray<readonly [string, string | null]> = [
  ["queued", "Q"],
  ["waiting", "Q"],
  ["in transit", "T"],
  ["moving", "T"],
  ["delivered", "D"],
  ["complete", "D"],
  ["failed", "F"],
  ["error", "F"],
  ["  QuEuEd  ", "Q"],
  ["\tIN\n  TRANSIT\r", "T"],
  ["  complete\t", "D"],
  ["", null],
  [" \t\n ", null],
  ["intransit", null],
  ["unknown", null],
  ["queued now", null],
];

for (const [input, expected] of cases) {
  equal(getDeliveryBadge(input), expected, `badge for ${JSON.stringify(input)}`);
}

const callerValue = "  Waiting  ";
equal(getDeliveryBadge(callerValue), "Q", "caller value result");
equal(callerValue, "  Waiting  ", "caller value remains unchanged");
equal(getDeliveryBadge("moving"), "T", "repeated calls remain independent");

